import type { HelpTopic, HelpImage, Parameter } from "../topics";

const shot = (path: string, caption: string): HelpImage => ({ path: `reference/${path}.png`, caption });
const feather: Parameter = ["Difuminado", "Suaviza el límite. 0 da un borde nítido y es el valor predeterminado de las herramientas nuevas; 1 usa toda la zona de difuminado disponible. Un modificador atenúa su efecto hacia el campo sin cambios; una herramienta de pintura atenúa su aportación. Los objetos existentes conservan el valor guardado."];
const edge: Parameter = ["Borde: Mezclar / Reemplazar", "Mezclar combina el vector nuevo con el existente a través de un borde suave. Reemplazar, en cambio, atenúa el vector nuevo hacia la calma. El interior nítido usa el vector nuevo en ambos modos. Las celdas de origen sin definir quedan transparentes en ambos modos."];
const size: Parameter = ["Tamaño y unidades", "Diámetro del pincel o anchura del cuadrado. px da proporciones de pantalla constantes en el momento de crear; km / nm da una distancia sobre el terreno. Hacer zoom después no cambia el tamaño de los objetos existentes. La unidad elegida se aplica también a los demás controles de tamaño de la herramienta."];
const brushShape: Parameter = ["Forma del pincel: Círculo / Cuadrado", "Elige el sello que se arrastra a lo largo del gesto. Círculo produce extremos redondeados; Cuadrado arrastra sellos cuadrados. Esta geometría queda fijada tras dibujar; la animación de forma puede remodelar un objeto existente."];
const speed: Parameter = ["Velocidad", "Módulo del vector en la unidad de velocidad global. Cero pinta calma definida, que no es lo mismo que una zona vacía."];
const direction: Parameter[] = [
  ["Modo de dirección", "Constante usa una única dirección de la rosa. Hacia un punto apunta a un objetivo, calculado por separado en cada posición; Alejándose de un punto invierte esa dirección. Solo se muestran las opciones pertinentes."],
  ["Dirección", "Grados en la convención de/hacia del proyecto. El norte es 0°, el este 90°, el sur 180° y el oeste 270°. Con el viento «de», 270° pinta un viento que se desplaza hacia el este."],
  ["Objetivo / Elegir en el mapa", "Introduzca la longitud y después la latitud, o pulse Elegir en el mapa y haga clic en el objetivo. La longitud positiva es este; la latitud positiva es norte. Ese clic de selección coloca el objetivo en lugar de pintar."],
  ["Dirección al objetivo: Ortodrómica / Loxodrómica", "Ortodrómica usa el rumbo local de la ruta esférica más corta. Loxodrómica usa un rumbo constante hacia el objetivo. Ambas pueden diferir considerablemente en rutas largas y en latitudes altas."],
  ["Ángulo respecto al objetivo", "Desvía la dirección resultante entre −180° y +180°. Cero apunta directamente hacia el objetivo o en sentido contrario. Los ángulos positivos giran en sentido horario; los negativos, en sentido antihorario."],
];
const eyedropper: Parameter = ["Cuentagotas", "Haga clic en él y después en una posición del mapa con datos definidos para copiar la velocidad y la dirección en la herramienta. Toma muestras de los datos visibles del tipo de campo activo. Está disponible en los modos de un solo vector, no en los degradados de dos extremos."];
const modifier = "Un objeto de edición modifica los datos que tiene debajo en su propia capa. No puede crear flujo sobre datos sin definir. Colóquelo por encima de los objetos a los que deba afectar. Su transformación, cantidad, duración y propiedades admitidas se pueden animar.";

/** Referencia integrada sin conexión. Los valores de las capturas son ejemplos, no valores predeterminados. */
const topics: HelpTopic[] = [
  { id: "workspace", group: "Espacio de trabajo", title: "Primeros pasos", paragraphs: [
    "VectorEffects crea campos animados de viento y de corriente de superficie a partir de objetos pintados, archivos GRIB, archivos históricos y macros capturadas. El lienzo contiene el mapa base. Las capas vacías son transparentes; solo los datos definidos y las superposiciones de imagen tapan lo que hay debajo.",
    "Esta referencia, con búsqueda, funciona sin conexión. Elija una página a la izquierda y haga clic en las capturas de pantalla para verlas a tamaño completo. Las capturas muestran proyectos de ejemplo de una beta anterior: los valores de difuminado distintos de cero son ejemplos, el ángulo de Círculo ahora usa un control deslizante y la antigua opción Absoluta de Curva ahora se llama Constante.",
  ], steps: ["Elija Nuevo… y defina la resolución de la malla, el paso de tiempo y el número de pasos.", "Seleccione una capa desbloqueada, elija Pincel, ajuste la velocidad y la dirección, y arrastre sobre el mapa.", "Seleccione el objeto nuevo para examinarlo o animarlo.", "Guarde como .veproj para conservar los objetos editables. Use Exportar GRIB… para obtener datos vectoriales que usar en otro programa."],
    images: [shot("overview/overview", "El mapa, las opciones de herramienta, las capas, las propiedades, el historial y la línea de tiempo.")], related: ["projects", "tools", "layers", "animation", "export"] },
  { id: "projects", group: "Espacio de trabajo", title: "Proyectos, guardado y recuperación", paragraphs: ["Use el menú Proyecto de la barra de título para Nuevo…, Abrir…, Guardar, Guardar como… y Cerrar. Un proyecto almacena su malla, su línea de tiempo, sus capas, su geometría y su animación. Mantenga los archivos de origen importados en las rutas a las que hace referencia al volver a abrir o al mover un proyecto. Conserve el archivo .veproj como original editable después de exportar."],
    parameters: [["Nuevo…: Nombre", "Da nombre al proyecto. Defina el tipo de campo de cada capa pintada en el panel de capas."], ["Resolución", "Separación geográfica de la malla. Una malla más fina resuelve detalles más pequeños, pero aumenta el tiempo de evaluación y el tamaño de la exportación."], ["Paso de tiempo / Pasos", "Horas simuladas entre pasos y número total de pasos. Son distintos de los fotogramas por segundo de la reproducción."], ["Abrir… / Recientes", "Abre un archivo .veproj. Recientes enumera los archivos existentes; use Abrir… para localizar un proyecto que se haya movido."], ["Guardar / Guardar como…", "Guardar actualiza el archivo actual. Guardar como… elige una ruta nueva. Un proyecto sin guardar necesita primero una ruta."], ["Cerrar", "Cierra el proyecto. Si hay trabajo sin guardar, ofrece Guardar, No guardar o Cancelar."], ["Guardado automático", "Ajustes permite conservar instantáneas de recuperación, guardar directamente en el archivo del proyecto o dejar el guardado en manual. Se activa cada minuto o cada cincuenta ediciones, lo que ocurra antes. Tras un cierre inesperado, la página de inicio ofrece recuperar el trabajo."], ["Deshacer / Rehacer / Historial", "Invierten o vuelven a aplicar las ediciones del documento; Historial las describe. Un gesto completo es una sola edición, de modo que un Deshacer elimina un trazo o restaura una región borrada."]],
    images: [shot("overview/project_management", "Controles del proyecto y el engranaje de Ajustes.")], related: ["settings", "export", "troubleshooting"] },
  { id: "view", group: "Espacio de trabajo", title: "Vista del mapa y convenciones de dirección", paragraphs: ["Desplace el mapa con la herramienta Mano y haga zoom con la rueda o el trackpad. Los ajustes de la vista afectan a la presentación, no a los vectores exportados."],
    parameters: [["Captura", "Entra en el modo de captura de macros para grabar una región a lo largo de los fotogramas."], ["Medir", "Abre los anillos de distancia, el compás de puntas, las comparaciones de rutas y la velocidad de desplazamiento. Las mediciones no pintan datos vectoriales."], ["Glifos", "Muestra u oculta las direcciones: barbas meteorológicas para el viento y flechas para las corrientes."], ["Proyección", "Busque entre 270 vistas por nombre, país o código EPSG: mapas cilíndricos y mundiales, un globo ortográfico, mapas azimutales, mallas polares norte/sur, mallas nacionales y todas las zonas UTM de WGS84. Los mapas regionales se ajustan a su zona de uso; arrastrar un globo o un mapa azimutal cambia su centro. La proyección personalizada acepta PROJ, WKT o un código EPSG incluido. Las definiciones funcionan sin conexión; no se incluyen las mallas de corrección de datum geodésico. Esto cambia la vista, no los datos almacenados ni las exportaciones. En las vistas curvas, los tamaños en píxeles se convierten en geometría sobre el terreno en el punto de inicio del gesto."], ["Retícula", "Muestra las líneas de referencia de longitud y latitud."], ["Escala automática", "Ajusta los máximos de la escala de color a los datos visibles. Desactívela para comparar con las escalas fijas del proyecto."], ["Leyenda", "Muestra el degradado, el tipo de campo, las unidades de velocidad y los límites de la escala."], ["Lectura", "Muestra las coordenadas del puntero, la velocidad y la dirección muestreadas, y el zoom. «Sin campo» significa datos sin definir."], ["Flechas frente a barbas de viento", "Una flecha apunta hacia donde va la corriente. Una barba de viento apunta hacia donde viene el viento, con las plumas en ese extremo. La barba de un viento del norte apunta al norte, pero su flujo avanza hacia el sur. La convención numérica de dirección no invierte las barbas meteorológicas."]],
    images: [shot("overview/view_and_global_settings", "Captura, medición, deshacer/rehacer y controles de visualización del mapa.")], related: ["targets", "settings", "measure", "divergence"] },
  { id: "layers", group: "Espacio de trabajo", title: "Capas, apilamiento y filtros de velocidad", paragraphs: ["La lista muestra primero la parte superior de la pila. Las capas pintadas contienen objetos y son totalmente transparentes donde esos objetos no definen datos. El mapa base está debajo de la pila y no tiene fila de capa. Puede eliminar todas las capas; añada una capa nueva para volver a pintar o use Deshacer para restaurar una."],
    parameters: [["+ / Importar / Calendario / Antena", "Añaden una capa pintada; importan un archivo GRIB2, un almacén Zarr de enrutamiento, una imagen o datos SIG; o descargan datos históricos. La antena obtiene los últimos días de datos observados."], ["Nombre / triángulo desplegable", "Selecciona la capa o despliega su lista de objetos."], ["Asa de arrastre / flechas arriba y abajo", "Reordenan las capas arrastrando sus encabezados o con las flechas. Arrastre las filas de objetos para reordenarlos, o sobre otra capa para moverlos. Los objetos de edición y de clonación leen lo que tienen debajo en esa capa."], ["Ojo / candado", "Oculta una capa o impide editar sus objetos. Desbloquéela antes de dibujar o transformar."], ["Campo", "Selecciona el tipo de las capas pintadas. Las capas importadas indican el tipo de su origen. El viento y las corrientes siguen siendo campos separados."], ["Filtro de velocidad: mínimo / máximo", "Activa un intervalo de velocidad inclusivo en las unidades de visualización. Los valores fuera de él se vuelven transparentes. El filtro se aplica después de los objetos y las ediciones de la capa; todos los tipos de capa lo admiten. Los umbrales de imagen usan la velocidad vectorial en las posiciones de la imagen."], ["Duplicar / ×", "Duplica un objeto, elimina un objeto o elimina una capa y sus objetos. Deshacer restaura las eliminaciones del documento."]],
    images: [shot("overview/layer_panel", "Controles de capa y el filtro de velocidad opcional.")], related: ["selection", "imports", "history", "clone"] },
  { id: "selection", group: "Espacio de trabajo", title: "Selección, propiedades y transformaciones", paragraphs: ["Seleccione desde el panel de capas o con la herramienta de selección; Mayús-clic amplía la selección. Solo los objetos seleccionados aparecen en la vista previa en movimiento, aunque otros objetos se solapen con sus límites. Elegir una capa o dibujar una región puede cambiar el alcance de la selección."],
    parameters: [["Posición / Elegir", "Longitud y latitud del ancla. Elegir la asigna con un clic en el mapa. Arrastrar mueve el ancla; poner claves en Posición hace que se desplace."], ["Escala", "Cambia el tamaño alrededor del ancla. 100 % es el tamaño original. Cambia la geometría, no la velocidad de los vectores."], ["Rotación", "Gira el objeto y su campo alrededor del ancla. La herramienta de edición Rotar flujo, en cambio, gira los vectores sin mover la huella del campo."], ["Visible", "Activa el objeto; ponga claves para encenderlo y apagarlo a lo largo del tiempo."], ["Tiradores de transformación", "Mueven, giran o escalan la selección en el fotograma actual, según las reglas de los fotogramas clave."], ["Rombos de propiedad", "Añaden una clave en el fotograma seleccionado. La línea de tiempo muestra las mismas propiedades y sus claves."], ["Detalles de la capa", "Sin ningún objeto seleccionado, Propiedades describe la capa activa: origen, archivo o archivo histórico, tipo de campo y cobertura de fotogramas."], feather, edge],
    images: [shot("overview/properties_history", "Propiedades del objeto, rombos de animación e historial de ediciones.")], related: ["animation", "shape", "tools"] },
  { id: "tools", group: "Herramientas de creación", title: "Nociones básicas: tamaño, difuminado y bordes", paragraphs: ["Las opciones de herramienta definen los gestos nuevos; el panel de propiedades edita los objetos existentes. Después de cambiar una opción, el siguiente clic en el mapa usa la herramienta. Elegir en el mapa y el cuentagotas reservan deliberadamente un clic para elegir o muestrear.", "Un gesto completo se convierte en un objeto; los trazos compatibles pueden fusionarse según la herramienta activa y los ajustes. Las herramientas de creación pintan vectores, mientras que las de edición modifican los datos que tienen debajo. Solo se muestran las opciones con sentido en el modo actual."],
    parameters: [size, brushShape, feather, edge, eyedropper, ["Geometría en píxeles", "px significa píxeles en el momento de crear, también en latitudes altas. La geografía guardada permanece anclada al desplazar el mapa, hacer zoom o cambiar de proyección."], ["Elecciones de geometría fijas", "Elecciones como la forma de sello original quedan fijadas tras la creación. Use la animación de forma para remodelar el objeto en lugar de cambiar su modo de construcción."]],
    images: [shot("overview/tool_bar", "Mano, Seleccionar, Borrador, Insertar macro, Pincel, Círculo, Relleno de forma, Tampón de clonar, Curva, Máscara, Intensificar / reducir, Divergir / converger, Rotar flujo, Deformar y Desplazar.")], related: ["brush", "circle", "path", "eraser"] },
  { id: "brush", group: "Herramientas de creación", title: "Pincel", paragraphs: ["Arrastre para pintar un círculo o un cuadrado a lo largo del gesto; haga clic para un solo sello. Use un flujo constante u oriente cada vector hacia un objetivo o alejándose de él. El borde sigue el Difuminado y el modo de Borde."],
    parameters: [brushShape, size, speed, ...direction, feather, edge, eyedropper],
    images: [shot("create_tools/brush_tool_constant", "Un pincel con dirección de viento constante. El difuminado es un valor de ejemplo.")], related: ["targets", "tools", "animation"] },
  { id: "targets", group: "Herramientas de creación", title: "Rumbos hacia un objetivo y desvíos angulares", paragraphs: ["Los modos con objetivo hacen variar la dirección dentro de un objeto. Aparecen en Pincel y en el modo de vector constante de Relleno de forma. Mover o animar el objetivo cambia el punto de mira sin volver a dibujar la forma."],
    parameters: direction,
    steps: ["Elija Hacia un punto o Alejándose de un punto.", "Introduzca las coordenadas o use Elegir en el mapa.", "Elija Ortodrómica o Loxodrómica.", "Deje Ángulo respecto al objetivo en 0 para apuntar directamente, o introduzca un desvío.", "Pinte y compruebe varias posiciones con la lectura; las barbas de viento muestran la dirección de procedencia."],
    images: [shot("create_tools/brush_tool_point", "Coordenadas del objetivo, elección de ruta y desvío angular.")], related: ["view", "brush", "fill", "measure"] },
  { id: "circle", group: "Herramientas de creación", title: "Sello Círculo", paragraphs: ["Haga clic para colocar un flujo circular alrededor del puntero. Elija un disco, un anillo o un disco con degradado radial de velocidad. El ángulo inclina el flujo hacia dentro o hacia fuera conservando la velocidad elegida."],
    parameters: [["Relleno: Relleno / Perímetro / Relleno con degradado", "Relleno pinta el disco a la Velocidad indicada. Perímetro deja su centro sin definir. Relleno con degradado hace variar la velocidad del centro al borde."], ["Diámetro / Anchura del anillo", "Diámetro exterior y grosor de la banda perimetral. Ambos usan la unidad px o de terreno seleccionada."], speed, ["Velocidad (centro) / Velocidad (borde)", "Velocidades de los extremos para Relleno con degradado. Un centro a cero es calma definida, no un hueco vacío."], ["Rotación: Horario / Antihorario", "Circulación en sentido horario o antihorario con un ángulo tangente de cero."], ["Ángulo respecto a la tangente", "Control deslizante de −90° a +90°. −90° apunta directamente hacia dentro; 0° sigue la tangente; +90° apunta hacia fuera. Los valores intermedios producen un flujo en espiral. El valor se indica en grados."], feather, edge],
    images: [shot("create_tools/circle_tool", "Parámetros de Círculo. El ángulo respecto a la tangente usa ahora un control deslizante de −90° a +90°.")], related: ["tools", "divergence", "shape"] },
  { id: "fill", group: "Herramientas de creación", title: "Relleno de forma y degradados vectoriales", paragraphs: ["Pinte una forma predefinida arrastrada o un polígono. El contorno determina dónde existen datos; el Modo vectorial determina los vectores del interior. Un degradado mezcla los vectores de los extremos, de modo que direcciones distintas en los extremos también pueden cambiar la velocidad entre ellos."],
    parameters: [["Forma: Polígono / Cuadrado / Rectángulo / Círculo", "Haga clic en los vértices del polígono y termine con Intro o doble clic. Arrastre para trazar una forma predefinida. Esc cancela una construcción sin terminar."], ["Forma en", "Las unidades de terreno definen una geometría geográfica; px usa el plano de pantalla cilíndrico actual, o un tamaño local sobre el terreno en las vistas de globo, azimutales y regionales."], ["Modo vectorial: Constante / Degradado", "Constante usa una velocidad y el modo de dirección. Degradado reparte los vectores inicial y final por la forma."], speed, ...direction, ["Velocidad (inicio) / Velocidad (final)", "Módulos en los extremos opuestos del degradado."], ["Dirección (inicio) / Dirección (final)", "Direcciones de los extremos en la convención de/hacia del proyecto."], ["Eje del degradado", "Rumbo geométrico desde el inicio del degradado hacia su final. Es un eje, no una dirección de procedencia del viento."], feather, edge],
    images: [shot("create_tools/shape_fill", "Un polígono con un degradado vectorial.")], related: ["targets", "shape", "selection"] },
  { id: "clone", group: "Herramientas de creación", title: "Tampón de clonar y transparencia", paragraphs: ["El tampón de clonar copia los vectores que tiene debajo en la misma capa, no el mapa base ni los colores de fondo. Los huecos del origen siguen siendo transparentes durante la vista previa y después de soltar. Un origen de velocidad cero realmente definido se sigue copiando como calma.", "Los objetos de origen se evalúan en el fotograma actual, de modo que sus cambios y su animación pueden cambiar el clon. Los objetos situados por encima del clon no pasan a ser su origen."],
    parameters: [brushShape, size, ["Origen / Elegir en el mapa", "Coordenadas del ancla de origen. Elíjalas antes de pintar el destino."], ["Desfase: Alineado", "Mantiene el desfase entre el ancla de destino y el origen. A medida que se mueve la posición de muestreo, su origen se mueve en la misma medida."], ["Desfase: Fijo", "Reinicia el muestreo alrededor del origen elegido en cada sello a lo largo del trazo, aplicando repetidamente esa zona de origen."], feather, edge],
    steps: ["Active la capa que contiene los objetos de origen.", "Elija Tampón de clonar y elija un origen con datos definidos.", "Ajuste el tamaño, el modo de desfase y el difuminado.", "Pinte el destino. Las celdas de origen sin definir lo dejan sin cambios."],
    images: [shot("create_tools/clone_stamp", "Controles de Origen y Desfase sobre un campo clonado.")], related: ["layers", "tools", "troubleshooting"] },
  { id: "path", group: "Herramientas de creación", title: "Herramienta Curva", paragraphs: ["Pinte un corredor para una corriente en chorro, un frente o un canal. Coloque los puntos de la ruta y termine con Intro o doble clic. Esc abandona un trazado sin terminar. El flujo puede seguir la ruta o mantenerse constante."],
    parameters: [["Curva: Polilínea / Bézier", "Polilínea une los vértices con segmentos rectos. Bézier ofrece segmentos curvos y tiradores de control."], ["Anchura", "Anchura total del corredor en px o en unidades de terreno."], speed, ["Modo de dirección: Constante", "Una única dirección de la rosa en todo el corredor. Las versiones anteriores lo llamaban Absoluta; el comportamiento no ha cambiado."], ["Modo de dirección: Relativa al trazado", "Usa la tangente local. Una dirección de 0° sigue el orden de los puntos, 180° fluye en sentido contrario y 90° lo cruza."], ["Dirección", "Un rumbo de la rosa en el modo Constante, según la convención del proyecto; un desvío geométrico respecto a la tangente en el modo Relativa al trazado. Los desvíos no se convierten en rumbos de procedencia del viento."], feather, edge, eyedropper],
    images: [shot("create_tools/path_tool", "Un corredor cuyos vectores siguen su ruta.")], related: ["tools", "shape", "animation"] },
  { id: "mask", group: "Herramientas de edición", title: "Máscara", paragraphs: ["Una máscara elimina la cobertura de los datos anteriores de su capa y deja ver las capas inferiores. Sigue siendo un objeto editable y animable. Borrar, en cambio, elimina geometría de forma destructiva."],
    parameters: [brushShape, size, feather, ["Invertir", "Desactivado, enmascara el interior de la huella. Activado, enmascara el exterior y limita los datos anteriores de la capa a esa región."], edge],
    images: [shot("edit_tools/mask_tool", "Una máscara que atraviesa formas pintadas.")], related: ["eraser", "layers", "shape"] },
  { id: "intensity", group: "Herramientas de edición", title: "Intensificar / reducir", paragraphs: [modifier, "Cambia la velocidad conservando la dirección. Un vector nulo sigue en calma."],
    parameters: [size, ["Cantidad", "Control deslizante de −100 % a +200 %. Cero no hace nada; +100 % duplica la velocidad; +200 % la triplica; −50 % la reduce a la mitad; −100 % produce calma definida. El difuminado mezcla hacia la velocidad original en el borde."], feather],
    images: [shot("edit_tools/intensify_tool", "Aumento de la velocidad bajo la huella de un modificador.")], related: ["divergence", "rotation", "layers"] },
  { id: "divergence", group: "Herramientas de edición", title: "Divergir / converger", paragraphs: [modifier, "Divergir desvía el flujo alejándolo del centro de la huella o del eje del trazo; converger lo desvía hacia él. La velocidad se conserva. Las barbas de viento apuntan hacia el viento entrante: sus astas pueden apuntar hacia dentro cuando el flujo real diverge.", "Para un flujo hacia el norte al este del centro de un sello, Divergir añade una componente hacia el este; Converger añade una componente hacia el oeste."],
    parameters: [size, ["Cantidad: Divergencia (hacia fuera)", "El lado izquierdo desvía el flujo hacia fuera. Una cantidad mayor añade una componente radial más fuerte antes de restaurar la velocidad original."], ["Cantidad: Convergencia (hacia dentro)", "El lado derecho desvía el flujo hacia dentro. El centro es neutro. El porcentaje es la intensidad del efecto, no un cambio de velocidad."], feather],
    images: [shot("edit_tools/convergence_divergence_tool", "Divergencia sobre datos de viento; las barbas indican la dirección de procedencia.")], related: ["view", "circle", "rotation"] },
  { id: "rotation", group: "Herramientas de edición", title: "Herramienta de edición Rotar flujo", paragraphs: [modifier, "Gira los vectores en su sitio, manteniendo su huella y sus rasgos espaciales donde estaban."],
    parameters: [size, ["Sentido de giro: Horario / Antihorario", "Sentido en que se gira el flujo subyacente."], ["Cantidad", "De 0° a 180°. Cero es neutro, 90° gira el flujo de lado y 180° invierte la dirección. La velocidad se conserva."], feather],
    images: [shot("edit_tools/rotation_tool", "Giro de 30° de los vectores subyacentes.")], related: ["selection", "warp", "intensity"] },
  { id: "warp", group: "Herramientas de edición", title: "Deformar y desplazar", paragraphs: [modifier, "Deformar mueve las posiciones de muestreo para empujar o retorcer los rasgos del campo. Desplazar es una herramienta de dos pasos: pinte para seleccionar una zona, suelte y luego arrastre la selección a su nueva posición. Con el Difuminado a cero, el campo seleccionado se mueve intacto; el Difuminado suaviza su borde interior y conserva el núcleo. Ambos límites permanecen resaltados, con una línea que une sus centros. La zona que queda libre y una banda alrededor del destino se interpolan para ajustarse al campo circundante. Esc cancela la selección pendiente."],
    parameters: [size, ["Deformar: Empuje", "Desplaza el campo hacia el punto de Empujar hacia. Arrastrar con Mayús define el tirón desde el ancla hasta su destino."], ["Empujar hacia", "Coordenadas de destino comunes a todos los fotogramas. Empujar hacia no admite claves; Posición sí puede animar la colocación del objeto."], ["Deformar: Torsión", "Retuerce el muestreo alrededor del ancla."], ["Torsión", "Ángulo con signo de −360° a +360°. Cero es neutro; el signo cambia el sentido de giro."], ["Desplazar: Distancia de interpolación", "Hasta dónde se extiende la interpolación fuera del límite de destino, en la unidad de distancia px o geográfica del pincel. Con cero, la zona de origen que queda libre se rellena igualmente."], ["Animación de Desplazar", "Posición de la selección, Posición del desplazamiento (relativa), Difuminado y Distancia de interpolación tienen pistas independientes. Posición del desplazamiento tiene coordenadas emparejadas con claves y suavizado compartidos. Arrastre con Mayús la selección de origen para poner una clave en su destino relativo con Clave automática. Desplazar no tiene animación de forma."], feather],
    images: [shot("edit_tools/warp_tool", "Modo Torsión con tamaño, ángulo y difuminado.")], related: ["rotation", "selection", "shape"] },
  { id: "eraser", group: "Herramientas de edición", title: "Borrador y cortes destructivos", paragraphs: ["El borrador elimina geometría de los objetos o de los datos de la capa activa. No pinta fondo ni valores de velocidad cero. Deshacer restaura el corte; use una máscara para obtener un recorte independiente y eliminable.", "Los cortes permanecen aunque cambien los perímetros animados. Seleccionar Borrador sale de la edición de forma y oculta los puntos del perímetro."],
    parameters: [brushShape, size, feather], steps: ["Active y desbloquee la capa deseada.", "Elija Círculo o Cuadrado y un tamaño en px o en unidades de terreno.", "Use Difuminado 0 para un corte limpio o auméntelo para suavizarlo.", "Arrastre sobre la región no deseada. Deshacer la restaura."],
    images: [shot("utility_tools/eraser", "Un borrador de 400 píxeles en Mercator.")], related: ["mask", "shape", "layers"] },
  { id: "animation", group: "Animación", title: "Fotogramas clave y movimiento", paragraphs: ["El cabezal de reproducción elige el fotograma que se edita. Despliegue un objeto para ver sus propiedades animables. Los rombos son claves; entre ellas, los valores siguen su interpolación. Vaya a un fotograma, añada un rombo y edite las propiedades o los tiradores del mapa.", "Clave automática puede crear claves mientras edita. Los modos de dirección, el Relleno de Círculo, el Desfase de Tampón de clonar, Invertir de Máscara y el modo/Empujar hacia de Deformar se aplican a todo el objeto y no admiten claves. Cuando una propiedad ya tiene claves, editarla en otro fotograma añade una clave en lugar de cambiar toda la animación."],
    parameters: [["Reproducir / Pausa / Detener", "Reproducir avanza desde el fotograma actual; Pausa lo mantiene; Detener vuelve al principio."], ["Bucle", "Repite la reproducción después del último fotograma."], ["pasos/s", "Fotogramas por segundo de visualización solicitados, independientes de las horas simuladas por fotograma. Los datos importados aún no preparados pueden tardar en cargarse."], ["Clave automática", "Controla la creación automática de claves al editar propiedades animables."], ["Pasos", "Número total de fotogramas. Acortar la línea de tiempo puede eliminar claves posteriores y requiere confirmación."], ["Tiempo / Añadir hora de inicio / ×", "Define o elimina la hora de inicio UTC. Sin ella, la regla muestra horas relativas; con ella, se dispone de fechas UTC absolutas."], ["Barra de preparación", "Muestra los fotogramas preparados. Los conjuntos de datos importados grandes necesitan tiempo para la preparación inicial."], ["Gráfico de valores / interpolación", "Despliegue una propiedad para examinar sus valores a lo largo del tiempo. Haga clic con el botón derecho en una clave para elegir la interpolación disponible para el tramo que sale de ella."], ["Selección de claves", "Haga clic en las claves para seleccionarlas, arrástrelas para moverlas y pulse Supr para eliminarlas. Las claves seleccionadas tienen prioridad sobre la eliminación de objetos."]],
    images: [shot("overview/timeline", "Transporte, velocidad de reproducción, clave automática, hora y barras de duración."), shot("timeline/keyframes", "Claves de propiedad y puntos de los fotogramas intermedios.")],
    sections: [{ heading: "Moverse a velocidad constante", paragraphs: ["Haga clic en →+ en Posición. El movimiento empieza en el fotograma seleccionado y termina en la siguiente clave de posición, o en el último fotograma del objeto si no hay ninguna clave posterior."], parameters: [["Dirección hacia (° verdaderos)", "Dirección del desplazamiento: 0° norte, 90° este, 180° sur, 270° oeste. Siempre «hacia», con independencia de que el viento se muestre como «de»."], ["Velocidad", "Velocidad de desplazamiento en la unidad de velocidad global."], ["Añadir movimiento / Cancelar", "Crea la trayectoria del intervalo indicado o cancela. Las claves existentes en el intervalo requieren confirmación antes de sustituirse. Un Deshacer restaura la pista anterior."]], images: [shot("timeline/position_constant_motion", "El control →+ en Posición."), shot("timeline/position_constant_motion_dialog", "Dirección y velocidad de desplazamiento para el intervalo indicado.")] }],
    related: ["spans", "shape", "links", "motion-vectors"] },
  { id: "spans", group: "Animación", title: "Duración del objeto: fotogramas inicial y final", paragraphs: ["La barra de duración fija los fotogramas, inclusive, en los que un objeto contribuye. Es independiente de las claves de animación: un objeto puede tener una pista de movimiento larga y estar activo solo durante parte de ella."],
    parameters: [["Tirador de inicio", "Arrastre el asa izquierda para fijar el primer fotograma activo. Su zona sensible al clic se extiende más allá de la fina barra pintada."], ["Tirador de fin", "Arrastre el asa derecha para fijar el último fotograma activo."], ["Cuerpo de la barra", "Arrástrelo para mover todo el intervalo conservando su longitud. Hacer clic sin mover selecciona el objeto."], ["Vista previa al soltar", "La barra mantiene la posición en que se soltó mientras se actualizan las filas del documento, sin volver de golpe al intervalo anterior."]],
    images: [shot("timeline/keyframes", "La barra de duración está encima de las pistas de cada propiedad.")], related: ["animation", "macros", "shape"] },
  { id: "shape", group: "Animación", title: "Animar la forma de un objeto", paragraphs: ["La animación de forma es un modo de edición para los objetos de creación y de edición, salvo las macros capturadas, los parches y las selecciones de Desplazar. Los puntos del perímetro conservan su identidad entre claves y solo aparecen mientras está activado el botón de forma del objeto."],
    steps: ["Seleccione el objeto y haga clic en el icono de perímetro junto a su nombre en la línea de tiempo.", "En el fotograma deseado, arrastre los puntos y añada una clave de Forma con su rombo si es necesario.", "Vaya a otro fotograma y vuelva a mover los puntos.", "Recorra la línea de tiempo para examinar el contorno cambiante.", "Haga clic de nuevo en el icono de perímetro o elija otra herramienta para salir del modo y ocultar los puntos."],
    parameters: [["Puntos del perímetro", "Posiciones a lo largo del contorno en el fotograma actual. Pertenecen a la animación del objeto, no son objetos independientes."], ["Pista de Forma / rombo", "Almacena un contorno en un fotograma. Otras claves definen los contornos entre los que se interpola."], ["Interacción con el borrador", "Los cortes siguen siendo destructivos y no se restauran por el mero hecho de que el contorno cambie después."]],
    images: [shot("timeline/shape_keyframes", "Puntos del perímetro y una pista de Forma con claves.")], related: ["animation", "eraser", "selection"] },
  { id: "links", group: "Animación", title: "Vincular posición o rotación", paragraphs: ["Un vínculo de seguimiento hace que una propiedad siga la propiedad correspondiente de un objeto principal, de modo que los rasgos se muevan o giren juntos."],
    steps: ["Despliegue ambos objetos.", "Haga clic en el control de vínculo de Posición o Rotación del seguidor.", "Haga clic en la fila de esa propiedad del objeto principal. Un nuevo clic en el control armado cancela.", "Edite la pista del objeto principal. Haga clic en el vínculo activo para desvincular antes de crear una pista independiente."],
    parameters: [["Control de vínculo", "Arma, indica o elimina un vínculo de seguimiento. También se puede arrastrar entre las filas correspondientes."], ["Rombos seguidos", "Representan la animación del objeto principal. Edítelos en la fila del principal en lugar de tratarlos como claves independientes del seguidor."]],
    images: [shot("timeline/link_motion_to_object", "Una fila de Posición seguida con la información sobre herramientas para desvincular.")], related: ["animation", "motion-vectors"] },
  { id: "motion-vectors", group: "Animación", title: "Añadir el movimiento del objeto a sus vectores", paragraphs: ["Mover una forma y cambiar sus vectores pintados son decisiones independientes. La contribución del movimiento añade el desplazamiento del objeto al campo. No crea una trayectoria: primero anime las transformaciones y después active sus contribuciones.", "Los vectores de movimiento se combinan con los vectores originales, de modo que pueden cambiar tanto la velocidad como la dirección."],
    parameters: [["Contribución del movimiento (⇢)", "Añade el movimiento asociado a esa transformación. Posición aporta la velocidad de desplazamiento; las contribuciones disponibles de Escala y Rotación tienen en cuenta sus transformaciones cambiantes."], ["Movimiento constante (→+)", "Crea una trayectoria de Posición. Es distinto de añadir movimiento a los vectores pintados."], ["Transformación estática", "Una transformación que no cambia no aporta movimiento, aunque el control esté activado."]],
    images: [shot("timeline/add_motion_vectors", "Contribución del movimiento activada en una pista de Posición con claves.")], related: ["animation", "links", "macros"] },
  { id: "imports", group: "Datos y macros", title: "GRIB, Zarr e imágenes de referencia", paragraphs: ["Las importaciones GRIB y Zarr de enrutamiento añaden los campos de viento y de corriente admitidos como capas separadas. Cada fotograma usa la hora de origen asignada a ese paso del proyecto. Las imágenes son referencias visuales y no contienen datos vectoriales exportables."],
    parameters: [["Importar", "Un solo botón para todo archivo del que pueda salir una capa. El diálogo muestra solo lo que lee: GRIB2 (.grib2, .grb2, .grib, .grb), un almacén Zarr de enrutamiento, imágenes (.tif, .tiff, .png, .jpg, .jpeg) y datos SIG (.geojson, .json, .shp, .kml, .kmz, .gpx). Un GeoTIFF se convierte en una capa de imagen."], ["Archivo GRIB2", "Elija el archivo; examine su campo, sus fotogramas, su ruta y su cobertura en Detalles de la capa. Manténgalo disponible para volver a abrir el proyecto."], ["Almacén Zarr / Abrir desde Zarr", "Con Importar, elija el archivo zarr.json en la raíz del almacén de enrutamiento; se importa su directorio. El viento y las corrientes pasan a ser capas editables normales. Abrir desde Zarr en la pantalla de inicio elige el directorio y además toma del almacén la malla y el reloj del proyecto, dentro del límite de 240 fotogramas. Mantenga el directorio original disponible para volver a abrir el proyecto."], ["Celdas de fotogramas importados", "Seleccione fotogramas en la fila de la capa de origen en la línea de tiempo. Copiar, pegar y eliminar actúan sobre esos fotogramas en lugar de sobre las claves de objeto. Mayús amplía una serie."], ["Imagen", "Elija una imagen de referencia y su ubicación geográfica."], ["Tamaño y forma de la imagen", "Seleccione la capa de imagen y use la herramienta Mano. Arrastre una esquina para redimensionar proporcionalmente, o un tirador lateral para estirar la anchura o la altura. La esquina o el lado opuesto permanece fijo. Arrastre dentro de la imagen para moverla. Deshacer revierte todo el arrastre."], ["Opacidad de la imagen", "Controla en qué medida la imagen cubre el lienzo."], ["Filtro de velocidad", "Limita la cobertura del campo a un intervalo aceptado; los filtros de imagen usan la velocidad en las posiciones de la imagen."], ["Archivo no encontrado", "Restaure la ruta a la que se hace referencia o vuelva a importarlo. Los datos que faltan no se tratan como calma real."], ["Capa desalineada", "En una línea de tiempo con hora de inicio, una capa de archivo cuyo primer campo no está a la hora del paso en que cae se resalta en la línea de tiempo, con el desfase en su información. No se bloquea nada y la exportación no cambia. El botón junto al nombre mueve los campos a los pasos cuyas horas les corresponden; los pasos ocultos, pegados y borrados se mueven con ellos. Un deshacer lo restituye."]], related: ["history", "layers", "export"] },
  { id: "history", group: "Datos y macros", title: "Descargar viento y corrientes históricos", paragraphs: ["El calendario del panel de capas abre la importación histórica. Elija las fechas UTC y los archivos históricos; cada uno se convierte en una capa. Las descargas en caché pueden reutilizarse al volver a una solicitud o reintentarla."],
    parameters: [["Inicio (UTC) / Fin (UTC)", "Extremos inclusivos en horas enteras. Los intervalos más largos implican más fotogramas y descargas; revise el resumen de la carga de trabajo."], ["Fijar el inicio de la línea de tiempo", "Alinea el inicio del proyecto con la primera hora UTC solicitada."], ["Viento ERA5", "Selecciona el archivo histórico de viento a 10 m ofrecido."], ["GlobCurrent", "Selecciona el archivo histórico de corriente superficial total ofrecido."], ["Importar / Cancelar", "Inicia la solicitud seleccionada o deja el proyecto sin cambios antes de empezar."], ["Progreso", "El panel inferior informa de la descarga y la preparación. Ambos archivos históricos o los intervalos más largos aumentan el trabajo."], ["Reintentar la descarga", "Aparece junto a un error en el panel inferior y repite la solicitud guardada, reutilizando los datos en caché. Navegar por el mapa no la descarta."]],
    images: [shot("layers/import_history", "Fechas UTC, elección de archivos históricos, alineación y resumen de la carga de trabajo.")], related: ["imports", "nrt", "animation", "capture", "troubleshooting"] },
  { id: "nrt", group: "Datos y macros", title: "Descargar viento y corrientes en tiempo casi real", paragraphs: ["El botón de la antena, junto al calendario del panel de capas, descarga los últimos días de datos observados, hasta ahora, de los productos que marque, y añade una capa por cada uno. Lo descargado se escribe en disco, de modo que el proyecto se abre después sin conexión. Solo se accede a la red al pulsar Importar.", "Los productos van aproximadamente un día por detrás del presente, por lo que los pasos más recientes suelen quedar vacíos. Un producto diario, como DUACS, se muestra en todos los pasos de su día. Un producto que no puede descargarse se nombra en la barra de estado, y los demás llegan igualmente. Las capas se comportan como las capas GRIB importadas: admiten el filtro de velocidad, el borrador y la exportación. Las capas de temperatura superficial del mar son la excepción: se dibujan bajo el campo y se leen bajo el puntero, y nunca se filtran, se borran ni se exportan."],
    parameters: [["Días", "Cuántos días antes de hoy (UTC) empieza el periodo, a las 00:00; siempre termina ahora. El mayor número ofrecido es el que cabe en una línea de tiempo de 240 pasos con el paso del proyecto."], ["Fijar / Mover el inicio de la línea de tiempo", "Asigna al primer paso del proyecto el inicio del periodo, para que las fechas de la línea de tiempo coincidan con los datos. Dice Mover cuando el proyecto ya tiene una hora de inicio."], ["Alargar la línea de tiempo", "Se ofrece cuando el periodo necesita más pasos de los que tiene el proyecto. Añade pasos para que la línea de tiempo llegue al presente; nunca la acorta. Sin marcar, solo se descargan las horas que los pasos existentes pueden mostrar."], ["Copernicus MULTIOBS", "Corriente superficial total —geostrófica, de deriva por el viento y de marea—, horaria, a 0,25°."], ["Copernicus DUACS", "Corriente superficial geostrófica obtenida por altimetría satelital, diaria; se muestra en todos los pasos de su día."], ["Viento L4 de Copernicus", "Viento a 10 m que combina satélite y modelo, horario."], ["ASCAT Metop-B/C", "Viento a 10 m por dispersómetro desde los dos satélites Metop, una capa por día con las pasadas del día combinadas; sin valor donde no pasó ningún satélite."], ["CCMP NRT", "Viento a 10 m de CCMP (Cross-Calibrated Multi-Platform), versión 2.1 casi en tiempo real, cada 6 horas a 0,25°, de Remote Sensing Systems, leído del servidor OceanWatch de la NOAA. Cubre de 78° S a 78° N; no se muestra nada más cerca de los polos."], ["NOAA Blended Seawinds", "La combinación de NOAA del viento a 10 m de todos los escaterómetros y radiómetros en órbita, cada seis horas a 0,25°, de NOAA CoastWatch. Cada día es un archivo con sus cuatro horas, que se descarga una sola vez."], ["NOAA OISST", "Temperatura superficial del mar por interpolación óptima de la NOAA, versión 2.1: diaria a 0,25°, a partir de satélites, buques y boyas, distribuida por NOAA NCEI. Añade una capa de temperatura superficial del mar."], ["NOAA Geo-Polar Blended", "Combinación de la NOAA de la temperatura superficial del mar medida por satélites geoestacionarios y de órbita polar, diaria, leída a 0,25° desde NOAA CoastWatch. Añade una capa de temperatura superficial del mar."], ["OSTIA (Met Office)", "Análisis operativo de la temperatura superficial del mar y del hielo (OSTIA) del Met Office, diario, leído a 0,2° desde el Copernicus Marine Service. Añade una capa de temperatura superficial del mar."], ["CMC", "El análisis diario de temperatura superficial del mar del Centro Meteorológico Canadiense, leído a 0,25° desde su malla de 0,1°, del archivo PO.DAAC de la NASA. Añade una capa de temperatura superficial del mar. Necesita un token de NASA Earthdata, configurado en Ajustes; sin él aparece atenuado."], ["Token de NASA Earthdata", "Se configura en Ajustes → NASA Earthdata. Se guarda en un archivo propio, solo se envía al archivo PO.DAAC de la NASA al descargar CMC y nunca se vuelve a mostrar ni se entrega a un cliente de IA."], ["Capa de temperatura superficial del mar", "Se dibuja bajo el campo en color, de −2 °C a 32 °C, con su propia leyenda y la temperatura bajo el puntero en la lectura. Solo de visualización: nunca se pinta sobre ella ni se exporta. La unidad se elige en Ajustes."], ["Coste", "El número de descargas y el tamaño aproximado en disco, mostrados antes de importar."]], related: ["history", "imports", "animation"] },
  { id: "capture", group: "Datos y macros", title: "Grabar y previsualizar una macro", paragraphs: ["La captura graba los datos vectoriales de una región a lo largo de los fotogramas, incluido opcionalmente su movimiento. Usa el tipo de campo activo; los colores del mapa base y las imágenes no son datos vectoriales."],
    steps: ["Elija el campo de origen y el primer fotograma.", "Entre en el modo de captura, elija una forma y dibuje la región.", "Active Grabar movimiento si es necesario y, a continuación, Iniciar captura.", "Vaya a fotogramas posteriores y mueva la región para seguir el rasgo.", "Termine la grabación para previsualizar el intervalo de fotogramas.", "Use Editar macro para revisarla, Guardar macro para darle nombre y almacenarla, o Cancelar para abandonarla."],
    parameters: [["Forma", "Contorno de la región que delimita los datos capturados."], ["Grabar movimiento", "Conserva el movimiento de la región de captura a lo largo de los fotogramas visitados."], ["Claves de grabación", "Posiciones de la región en los pasos visitados. Recorra la línea de tiempo para examinar la trayectoria entre ellas."], ["Vista previa", "Reproduce los datos capturados de forma aislada. Haga clic en el mapa para previsualizar la colocación en otro lugar."], ["Editar macro / Guardar macro / Cancelar", "Revisan, guardan en la biblioteca o abandonan la captura. Las demás ediciones del documento están desactivadas mientras se graba o se previsualiza."]],
    images: [shot("creating_macros/create_macro_select_frame_and_area", "Elija el primer fotograma y la región."), shot("creating_macros/record_macro_end", "Mueva la región en un fotograma posterior."), shot("creating_macros/record_macro_preview", "Vista previa antes de guardar.")], related: ["macros", "animation", "history"] },
  { id: "macros", group: "Datos y macros", title: "Insertar macros e interpolar fotogramas que faltan", paragraphs: ["Elija Insertar macro, seleccione una entrada de la biblioteca y haga clic para colocarla en el fotograma actual. El contorno que sigue al puntero previsualiza la colocación solo en la capa pintada seleccionada. Un cursor tachado significa que la macro no tiene datos que coincidan con el tipo viento/corriente de esa capa, o que la capa no puede aceptarla; no se coloca ningún objeto en otra capa. Una macro con ambos campos usa el campo que coincide con la capa seleccionada. Se convierte en un objeto con transformaciones y duración editables.", "La estrategia de interpolación aparece cuando los fotogramas grabados están más separados que los del proyecto, como una macro trihoraria en un proyecto horario. Esta estrategia se aplica a toda la macro y no se puede animar."],
    parameters: [["Selector de macros / Actualizar", "Seleccione una entrada de la biblioteca por nombre, duración, número de fotogramas e indicador de movimiento. Actualizar vuelve a cargar el contenido de la biblioteca."], ["Repetir fotogramas", "Predeterminado: mantiene el último fotograma grabado hasta el siguiente."], ["Fotogramas vacíos", "No muestra datos de la macro en los fotogramas intermedios y deja ver lo que hay debajo."], ["Interpolar", "Mezcla u y v por separado e interpola el movimiento grabado. La interpolación por componentes evita que una dirección dé una vuelta completa al pasar por el salto de rumbo."], ["Bucle", "Repite la secuencia grabada dentro de la duración activa del objeto."], feather, edge, ["Directorio de la biblioteca", "Se configura en Ajustes. Los proyectos en los que se insertan conservan sus propios fotogramas de macro, de modo que eliminar la biblioteca no quita las macros que ya están en un proyecto."]],
    images: [shot("creating_macros/insert_macro_hover", "El contorno de inserción sigue al puntero."), shot("creating_macros/insert_macro_clicked", "Una macro insertada y su barra de duración.")], related: ["capture", "spans", "motion-vectors", "settings"] },
  { id: "measure", group: "Mediciones", title: "Comparación entre ortodrómica y loxodrómica", paragraphs: ["Elija Ortodrómica / loxodrómica en Medir y haga clic en dos extremos. La ortodrómica, o círculo máximo, es la ruta esférica más corta, con un rumbo local cambiante. Una loxodrómica mantiene un rumbo constante y suele ser más larga."],
    parameters: [["Etiqueta GC", "Distancia y rumbo inicial de la ruta ortodrómica."], ["Etiqueta RL", "Distancia y rumbo constante de la loxodrómica."], ["Extremos", "Arrástrelos para revisar la comparación."], ["Alt-clic en un punto", "Elimina esa medición."], ["Borrar ortodrómica / loxodrómica", "Elimina todas las comparaciones de rutas y conserva las demás mediciones."], ["Borrar todo", "Elimina todas las anotaciones de medición, no los objetos vectoriales."]],
    images: [shot("global_utility_tools/great_circle_rhumb_line", "Curva ortodrómica y loxodrómica discontinua entre los mismos extremos.")], related: ["targets", "rings", "dividers"] },
  { id: "rings", group: "Mediciones", title: "Anillos de distancia", paragraphs: ["Elija Anillos de distancia y haga clic en un centro. Los anillos representan distancias sobre el terreno, por lo que una proyección puede deformar su aspecto."],
    parameters: [["Intervalo", "Distancia sobre el terreno entre anillos en la unidad de distancia global."], ["Anillos", "Número de anillos. El radio exterior es igual a Intervalo × Anillos."], ["Editar el último conjunto", "Los cambios actualizan el conjunto activo. Haga clic en otro lugar para añadir un conjunto; arrastre un tirador central para moverlo."], ["Alt-clic en un punto", "Elimina ese conjunto de anillos."], ["Borrar anillos de distancia / Borrar todo", "Borra los conjuntos de anillos o todos los tipos de medición."]],
    images: [shot("global_utility_tools/range_rings", "Veinte anillos a intervalos de 50 nm, con un radio exterior de 1000 nm.")], related: ["measure", "dividers", "settings"] },
  { id: "dividers", group: "Mediciones", title: "Compás de puntas y distancias de varios tramos", paragraphs: ["Elija Compás de puntas y haga clic en los sucesivos puntos de recorrido. Cada tramo muestra la distancia y el rumbo; la cadena indica la distancia acumulada. Las mediciones no alteran los vectores exportados."],
    parameters: [["Clic", "Añade un tramo desde el último punto de recorrido."], ["Intro / Esc", "Termina la cadena actual."], ["Tiradores de los puntos de recorrido", "Arrástrelos para revisar la ruta y recalcular las distancias."], ["Alt-clic en un punto", "Elimina esa medición."], ["Borrar compás de puntas / Borrar todo", "Borra las cadenas o todas las anotaciones de medición."]],
    images: [shot("global_utility_tools/dividers", "Una cadena de varios tramos con rumbos y distancias totales.")], related: ["measure", "rings"] },
  { id: "feature-speed", group: "Mediciones", title: "Velocidad y dirección de un sistema en movimiento", paragraphs: ["Elija Velocidad de desplazamiento en Medir para saber con qué rapidez y hacia dónde se desplaza una borrasca, un frente o un remolino. Haga clic en el sistema, lleve la línea de tiempo a un paso de tiempo posterior y vuelva a hacer clic en él. La línea entre las dos marcas se rotula con la velocidad media en la unidad de velocidad global y el rumbo que siguió el sistema; la distancia y el tiempo transcurrido se escriben junto a la segunda marca.", "Entre los dos clics la línea de tiempo solo avanza: los pasos anteriores se atenúan, y el recorrido de la regla, las teclas de paso y la reproducción se detienen en el paso de la primera marca. La dirección es un rumbo —hacia donde se dirige el sistema—, sea cual sea la convención de dirección que el proyecto use para el viento. Las mediciones no alteran los vectores exportados."],
    parameters: [["Primer clic", "Marca dónde está el sistema en el paso de tiempo actual e impide que la línea de tiempo retroceda."], ["Segundo clic", "En un paso de tiempo posterior, marca adónde se ha desplazado el sistema y completa la medición."], ["Esc / Cancelar", "Descarta la primera marca y libera la línea de tiempo."], ["Rótulos", "Velocidad media y rumbo a lo largo de la línea; distancia y horas transcurridas junto a la segunda marca."], ["Tiradores de las marcas", "Arrastre cualquiera de las marcas para revisar la medición. Los pasos de tiempo quedan como se marcaron."], ["Alt-clic en un punto", "Elimina esa medición."], ["Borrar velocidades de desplazamiento / Borrar todo", "Borra estas mediciones o todas las anotaciones de medición."]], related: ["dividers", "measure", "animation"] },
  { id: "settings", group: "Ajustes y exportación", title: "Temas, unidades, flechas y barbas de viento", paragraphs: ["Abra Ajustes con el engranaje o con el botón Ajustes de la página de inicio. La sección Apariencia ofrece Original (Medianoche), Salvia y verde azulado, Océano, Ciruela, Brasa y Papel, además de un tema personalizado. Los temas se aplican de inmediato en toda la aplicación y se conservan con independencia de los proyectos. Las unidades y los estilos de glifo son preferencias de la aplicación; las escalas de color y los degradados del proyecto se guardan en el proyecto. Las opciones de presentación no cambian los módulos ni las direcciones exportados."],
    parameters: [["Distancia: km / nm", "Convierte la entrada y las lecturas entre kilómetros y millas náuticas."], ["Velocidad: kt / mph / km/h", "Convierte los valores de las herramientas, las lecturas, las leyendas y los diálogos de movimiento. Los valores se convierten, no se reinterpretan."], ["Temperatura: °C / °F", "Convierte la temperatura superficial del mar de la leyenda y la lectura. La capa guarda °C; solo cambia lo que se muestra."], ["Flechas / Barbas de viento", "Controles de estilo y vistas previas separados para cada tipo de glifo."], ["Tamaño (%)", "Longitud del glifo como porcentaje de su tamaño normal en pantalla, del 25 % al 300 %."], ["Densidad", "Número y separación de los glifos. Una densidad mayor muestra más direcciones locales, pero puede saturar el mapa."], ["Grosor de línea", "Grosor del asta y de las plumas."], ["Color / Opacidad", "Color del glifo y transparencia general."], ["Atenuar según la velocidad", "Reduce la opacidad en el flujo más lento, manteniendo visible el viento en calma definido."], ["Sombra", "Añade contraste detrás de los glifos."], ["Color / opacidad de la sombra", "Color y transparencia independientes para la sombra."], ["Sombra X / Y (px)", "Desplazamiento horizontal y vertical de la sombra en píxeles."], ["Restablecer flechas / Restablecer barbas de viento", "Restaura el aspecto predeterminado de ese estilo."], ["Escalas de color del proyecto", "Velocidades máximas fijas de viento/corriente cuando Escala automática está desactivada."], ["Degradados del proyecto", "Mapas de color separados para viento y corriente, elegidos entre muestras."], ["Valores predeterminados para proyectos nuevos", "Límites de escala iniciales de viento/corriente para los proyectos que se creen después."], ["Atajos", "Haga clic en una asignación y pulse la combinación que la sustituye. Las asignaciones mostradas describen su configuración actual."], ["Guardado automático / biblioteca de macros", "Elija recuperación, guardado directo o guardado manual. Defina el directorio de macros o elimine entradas de la biblioteca. Eliminar de la biblioteca pide confirmación y conserva las macros ya insertadas en los proyectos."], ["Servicio MCP", "Permite que un cliente de IA de este ordenador controle la aplicación mediante el Model Context Protocol. Desactivado de forma predeterminada; activado, la sección muestra la dirección local y el token. Añadir a Claude Code y Añadir a Codex escriben el servicio en la configuración propia de ese cliente; tras renovar el token o cambiar el puerto, el mismo botón la actualiza. Añadir a Claude Desktop abre una extensión de VectorEffects en el propio instalador de Claude Desktop, donde usted la confirma; se instala una sola vez y sigue por sí sola un token o un puerto nuevos. Configuración para otros clientes contiene lo mismo como texto para copiar. Renovar token revoca el anterior. La barra de estado muestra MCP y la última herramienta mientras hay un cliente conectado."]],
    images: [{ path: "settings.png", caption: "Controles de apariencia separados para flechas y barbas de viento." }], related: ["view", "projects", "macros"] },
  { id: "export", group: "Ajustes y exportación", title: "Exportar GRIB2", paragraphs: ["Exportar GRIB escribe los vectores evaluados para otras aplicaciones. El diálogo pide el inicio del pronóstico y, al exportar, el destino. Se han eliminado los selectores de centro de origen y de precisión. Cada mensaje lleva «Created with VectorEffects».", "La exportación usa la malla del proyecto con independencia del zoom, el tamaño de la pantalla y la densidad de glifos. Conserve el archivo .veproj para seguir editando."],
    parameters: [["Elegir ubicación y exportar…", "Pide la ruta del archivo .grib2 de salida y comienza la exportación."], ["Inicio del pronóstico (UTC)", "Hora de referencia del pronóstico: año, mes, día y hora. Los desfases de los fotogramas se suman para obtener las horas de validez de los mensajes; compruébelas con el periodo histórico o de pronóstico previsto."], ["Tamaño estimado", "Un límite superior. Los campos dispersos y constantes pueden ser mucho más pequeños."], ["Progreso / Cancelar la exportación", "Informa del avance de la exportación, o la detiene sin cambiar el proyecto."], ["Datos sin definir", "Las celdas sin cobertura usan mapas de bits GRIB. No se escriben como cero. La calma pintada deliberadamente sigue siendo un cero definido."], ["Viento y corriente", "u y v se escriben por separado para cada fotograma y cada tipo de campo visible. Las capas ocultas no contribuyen."], ["Nota", "Cada mensaje contiene «Created with VectorEffects» en su sección de uso local. Es posible que un lector no lo muestre en los controles de pronóstico habituales."], ["Empaquetado automático", "Empaquetado simple estándar de 16 bits, con campos constantes compactos. No es necesario elegir la precisión."], ["Contenido de la vista excluido", "El mapa base, las imágenes, los glifos, los tiradores de selección y las mediciones no se convierten en vectores."], ["Exportar Zarr", "Escribe los mismos vectores evaluados como un directorio Zarr V3, con la disposición de enrutamiento: una matriz de datos Float16 de u10, v10, ucur y vcur con coordenadas de tiempo, parámetro, latitud y longitud, con la latitud desde 90° y la longitud desde -180°. Los fragmentos son de tres días por 10 grados, comprimidos con Zstd y agrupados en particiones por cuenca oceánica; las celdas sin cobertura son NaN y una región sin nada no se escribe en absoluto."]],
    images: [{ path: "export.png", caption: "El diálogo de exportación simplificado, con la hora de referencia UTC y la elección del destino." }],
    related: ["projects", "layers", "imports", "troubleshooting"] },
  { id: "troubleshooting", group: "Ajustes y exportación", title: "Solución de problemas", paragraphs: ["Compruebe primero la capa activa, el fotograma seleccionado y el tipo de campo. Deshacer ayuda a aislar una edición reciente. Guarde una copia antes de investigar un proyecto complejo."],
    parameters: [["No aparece nada", "Compruebe la visibilidad, el bloqueo, la duración del objeto y los filtros de velocidad. Las herramientas de edición necesitan datos definidos debajo. Una Cantidad neutra o una selección de Desplazar sin desplazamiento no hacen nada."], ["Primer clic tras un ajuste", "La siguiente pulsación normal confirma la entrada numérica y usa la herramienta. Elegir en el mapa, la captura y el cuentagotas reservan el clic para su acción indicada."], ["Clon vacío", "Los vectores de origen deben estar debajo del clon en la misma capa. Un origen vacío queda transparente; la calma definida se sigue copiando."], ["La divergencia parece invertida", "Las barbas apuntan hacia el viento entrante. Divergir desvía el flujo real hacia fuera; converger, hacia dentro."], ["El objeto ya no está en el proyecto", "Deshacer o eliminar puede quitar la selección. Las selecciones obsoletas y las respuestas de propiedades ahora se descartan. Si una edición real sigue fallando, vuelva a seleccionar la fila actual del objeto."], ["Reproducción lenta de datos importados", "Espere a la barra de preparación. Las lecturas iniciales de los archivos históricos y la evaluación pueden retrasar los pasos/s solicitados."], ["Error en la descarga histórica", "Use Reintentar la descarga junto al error. Si el archivo histórico sigue sin estar disponible, compruebe el periodo solicitado y la conexión."], ["Origen no encontrado / proyecto reciente", "Restaure la ruta a la que se hace referencia, o use Abrir / Importar para volver a encontrarlo. Las rutas de proyecto que faltan se quitan de la lista de recientes."], ["Caducidad de la beta", "Esta beta caduca el 1 de enero de 2027, según la fecha del sistema. Instale una versión actualizada para seguir usándola."]],
    related: ["layers", "clone", "divergence", "history", "export"] },
];

export default topics;
